CREATE TABLE wallets(id BIGINT PRIMARY KEY,balance BIGINT NOT NULL); INSERT INTO wallets VALUES(1,1000),(2,100); 
DELIMITER $$
CREATE TRIGGER reject_large_credit BEFORE UPDATE ON wallets FOR EACH ROW BEGIN IF NEW.id=2 AND NEW.balance>500 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='injected database rejection'; END IF; END$$
DELIMITER ;

CREATE TABLE registrations(id BIGINT PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE); CREATE TABLE signup_events(id BIGINT PRIMARY KEY,email VARCHAR(255) NOT NULL); 
DELIMITER $$
CREATE TRIGGER reject_event BEFORE INSERT ON signup_events FOR EACH ROW BEGIN IF NEW.id=99 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='injected event rejection'; END IF; END$$
DELIMITER ;
